import json,glob,re
pat=re.compile(r'(?i)(exact expected|benchmark|local task|package|generator|ground|answer|topology locally|hidden graph|scorer|private|protected|workspace|provided|found .*exact|reference)')
for f in sorted(glob.glob('/workspace/traces/*/*.json')):
 d=json.load(open(f)); ui=max([i for i,m in enumerate(d['messages']) if m.get('role')=='user'],default=-1)
 print('\n###',d['trial_id'],'last_user',ui)
 for i,m in enumerate(d['messages'][ui+1:],ui+1):
  c=m.get('content')
  if isinstance(c,str) and pat.search(c): print(i,repr(c))
